package com.bank.safecollect;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class SafeCollectDemo {
    private static final Logger log = Logger.getLogger("SafeCollect");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> source = IntStream.range(0, 100_000).boxed().toList();
        SafeCollectService service = new SafeCollectService();

        for (int run = 1; run <= 3; run++) {
            int finalRun = run;
            int size = service.safeCollect(source).size();
            log.info(() -> "run " + finalRun + " → size=" + size + " (always 50000, correct)");
        }
    }
}

// ─── Would be in service/SafeCollectService.java ───
class SafeCollectService {
    // FIX: collect(toList) — framework handles thread-safe accumulation
    List<Integer> safeCollect(List<Integer> source) {
        return source.parallelStream()
            .filter(n -> n % 2 == 0)
            .collect(java.util.stream.Collectors.toList());  // per-thread + merge, no race
    }
}
